import { initLanguage, localizedSearch, translate, awardTypeBadgeLabel } from './i18n.js';
import { programs, scholarships, sources, policy, filterPrograms, checked } from './data.js';
import { notes } from './notes.js';
import { rankingSources, rankingEdition, rankingCaveat, rankLabel, formatTuition, paginate } from './rankings.js';
import { awardRegionFilterMatch } from './award-filters.js';
import { PROGRAM_AREAS, programAreaByName, programAreaFilterTabs, rankingSourceShortLabel } from './areas.js';
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = formatTuition;
const external = (label,url) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
const confidenceTone = level => level === 'high' ? 'green' : level === 'medium' ? 'amber' : 'red';
const confidencePill = level => `<span class="pill ${confidenceTone(level)}">${esc(level)} confidence</span>`;
const outcomeSources = sources => `<div class="source-links">${sources.map(s => external(`${s.title} · accessed ${s.access_date}`, s.url)).join('')}</div>`;
const outcomeEmployers = o => Array.isArray(o.notable_employers) ? `<ul class="employer-list">${o.notable_employers.map(e => `<li>${esc(e)}</li>`).join('')}</ul>` : `<p>${esc(o.notable_employers)}</p>`;
const outcomeShortLine = o => { if (!o) return 'No outcome card yet'; const placement = String(o.full_time_placement); const short = placement.length > 72 ? `${placement.slice(0, 69)}…` : placement; return `<span translate="no" lang="en">${esc(short)} · ${confidencePill(o.confidence)}</span>`; };
function outcomeScopeBanner(o) {
 if (o.pathProgramId === 'umd-mscs') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Survey scope.</b> Department-wide Class of 2024 (not MS-only).</div></div>';
 }
 if (o.pathProgramId === 'nyu-mscs') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Courant MSCS only.</b> Do not attribute NYU Tandon master\'s-wide outcomes to Courant.</div></div>';
 }
 if (o.pathProgramId === 'harvard-seas-cs-ms') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Program label.</b> Computational Science &amp; Engineering interdisciplinary master\'s — not a standalone MS in Computer Science.</div></div>';
 }
 if (o.pathProgramId === 'upenn-mse-cis') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Penn CIS MSE.</b> SEAS-wide placement % is school-aggregate; keep MCIT separate.</div></div>';
 }
 if (o.pathProgramId === 'marshall-mba') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Class of 2025.</b> 71% employed within 90 days — softer than Marshall’s 2022–24 trend in a challenging market.</div></div>';
 }
 if (o.pathProgramId === 'kelley-mba') {
  return '<div class="notice amber"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Compensation basis.</b> Mean starting compensation ($163,279) includes signing bonus; mean base salary alone is not printed in the viewbook extract.</div></div>';
 }
 if (o.pathProgramId === 'caltech-cs-grad') {
  return '<div class="notice red"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>No terminal MS.</b> Caltech does not offer a standard terminal CS master’s — not a Fall 2027 master’s application target.</div></div>';
 }
 return '';
}
function outcomeRouteNotice(o) {
 const scope = outcomeScopeBanner(o);
 if (o.routeMismatch || (o.match !== 'same-route' && o.matchCaveat)) {
  const label = o.routeMismatch ? 'Route mismatch' : 'Route match caveat';
  const text = o.routeMismatchNotes || o.matchCaveat || '';
  const tone = o.routeMismatch && /suspended|not accept/i.test(text) ? ' red' : ' amber';
  return `${scope}<div class="notice${tone}"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>${label}.</b> ${esc(text)}</div></div>`;
 }
 return scope;
}
function outcomeCardBlock(o, { variant = 'primary' } = {}) {
 const variantPill = variant === 'adjacent' ? '<span class="pill amber">Adjacent route evidence</span>' : variant === 'specialty' ? '<span class="pill">Specialty program · not in ranking table</span>' : '';
 const programLabel = o.program ? `<p class="outcome-program"><strong>${esc(o.program)}</strong>${o.school ? ` · ${esc(o.school)}` : ''}</p>` : '';
 return `<div class="outcome-card ${variant}" translate="no" lang="en"><span class="pill">Original English evidence</span>${variantPill}<div class="badge-row">${confidencePill(o.confidence)}<span class="pill">Path batch · updated ${esc(o.last_updated)}</span>${o.routeMismatch ? '<span class="pill amber">Route mismatch</span>' : ''}</div>${programLabel}<p class="outcome-reason">${esc(o.confidence_reason)}</p>${outcomeRouteNotice(o)}<p><strong>Full-time placement:</strong> ${esc(o.full_time_placement)}</p>${o.full_time_placement_notes ? `<p>${esc(o.full_time_placement_notes)}</p>` : ''}<p><strong>Internship rate:</strong> ${esc(o.internship_rate)}</p>${o.internship_rate_notes ? `<p>${esc(o.internship_rate_notes)}</p>` : ''}<h4>Notable employers</h4>${outcomeEmployers(o)}${o.notable_employers_caveat ? `<p class="limit">${esc(o.notable_employers_caveat)}</p>` : ''}${o.notable_employers_notes ? `<p class="limit">${esc(o.notable_employers_notes)}</p>` : ''}<h4>Sources</h4>${outcomeSources(o.sources)}</div>`;
}
const careerSection = p => {
 const blocks = [];
 if (p.outcome) blocks.push(outcomeCardBlock(p.outcome));
 else blocks.push(`<p>${p.internship}</p>`);
 if (p.outcomeAdjacent?.length) {
  blocks.push(`<h4>Adjacent route evidence</h4><p class="limit">These cards research a different delivery format or route than the catalog row. They do not replace the primary card above.</p>${p.outcomeAdjacent.map(o => outcomeCardBlock(o, { variant: 'adjacent' })).join('')}`);
 }
 if (p.outcomeSpecialty?.length) {
  blocks.push(`<h4>Related specialty programs (research only)</h4><p class="limit">Not linked to this catalog row; shown for context only.</p>${p.outcomeSpecialty.map(o => outcomeCardBlock(o, { variant: 'specialty' })).join('')}`);
 }
 return `<h3>Internships & career support</h3>${blocks.join('')}`;
};
let selected = new Set();
try { selected = new Set(JSON.parse(localStorage.getItem('fieldnotes-compare') || '[]').filter(id => programs.some(p => p.id === id)).slice(0,4)); } catch {}
let page = 1, view = 'table', routeFilter = 'All routes';
let query = '', area = 'All programs', awardQuery = '', awardState = 'All records', awardHkFilter = 'All', awardTwFilter = 'All', awardPrcFilter = 'All', activeNote = 'README.md';
let toastTimer;
function toast(text) { $('#toast').textContent = text; $('#toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').hidden = true, 2600); }
function saveSelection(){ try { localStorage.setItem('fieldnotes-compare',JSON.stringify([...selected])); } catch {} }
const head = (kicker,title,description) => `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="intro">${description}</p></div><span class="pill"><span class="dot"></span> A living research collection</span></div>`;
const statusPill = p => `<span class="pill ${p.availabilityType === 'closed' ? 'red' : p.availabilityType !== 'verify' ? 'amber' : ''}">${esc(p.availability)}</span>`;
function programCard(p){return `<article class="program-card"><div class="card-body"><div class="card-top"><div class="school-mark ${p.color}" aria-hidden="true">${p.monogram}</div><span class="rank-badge">${rankLabel(p)} <small>U.S. News</small></span></div><h3>${esc(p.short)}</h3><p class="degree">${esc(p.degree)}</p>${statusPill(p)}<p class="card-summary">${esc(p.summary)}</p><div class="cost"><div class="cost-label"><span>${p.tuitionLabel}</span><span>${p.period}</span></div><div class="cost-number ${p.tuition === null ? 'unknown-cost' : ''}">${money(p.tuition)}</div><p class="cost-note">${p.costNote}</p></div><p class="deadline">${p.deadline}</p></div><div class="card-footer"><label class="compare-toggle"><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}> Compare<span class="sr-only"> ${esc(p.short)}</span></label><button class="button small" data-program="${p.id}">View research ↗</button></div></article>`;}
function rankingIntroBlurb() {
  const mba = programs.filter(p => p.area === 'Business').length;
  const cs = programs.filter(p => p.area === 'Computer science').length;
  const msf = programs.filter(p => p.area === 'Finance').length;
  return `<b>MBA:</b> ${mba} full-time business schools. <b>CS:</b> ${cs} graduate departments, including cutoff ties. CS department rank does not rank the individual master’s route. <b>MSF:</b> ${msf} programs in catalog (Finance area scaffold; ingest on hold).`;
}
function rankingIntro(){return `<div class="ranking-context"><div><span class="eyebrow">U.S. NEWS · ${rankingEdition.toUpperCase()}</span><h2>Separate ranking families. Different questions.</h2><p>${rankingIntroBlurb()}</p></div><details><summary>Ranking sources & limitations</summary><p>${rankingCaveat}</p>${Object.entries(rankingSources).map(([a,r])=>`<p><b>${rankingSourceShortLabel(a)}:</b> ${r.note} ${external(r.reproductionName,r.reproduction)} · ${external('Publisher',r.original)}</p>`).join('')}<a href="#notes/01-sources%2Fus-news-april-2026.md">Read the ranking record ↗</a> · <a href="#notes/05-finance%2FREADME.md">MSF id convention ↗</a></details></div>`;}
function programAreaStatsHtml() {
  return PROGRAM_AREAS.map(a => `<div class="stat"><strong>${programs.filter(p => p.area === a.area).length}</strong><div><span>${a.statTitle}</span><small>${a.statSubtitle}</small></div></div>`).join('')
    + `<div class="stat"><strong>${programs.filter(p => Number.isFinite(p.tuition)).length}</strong><div><span>Tuition references</span><small>2026–27 · Other costs pending</small></div></div>`;
}
function programAreaTabsHtml() {
  return programAreaFilterTabs().map(t => {
    const meta = programAreaByName(t);
    const label = meta ? meta.tabShort : t;
    return `<button data-area="${t}" aria-pressed="${area === t}">${label}</button>`;
  }).join('');
}
function showPrograms(){
 $('#main').innerHTML = head('YOUR FALL 2027 RESEARCH STARTS HERE','Find your next chapter.','Explore ranked MBA and graduate CS programs today, with the MSF (Finance) area scaffolded for a future slate — ties, degree routes and evidence kept in view.') + `<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">ONE INTAKE. DIFFERENT POSSIBILITIES.</div><h2 id="hero-title">Look beyond the ranking.<br>Understand the program.</h2><p>Browse the ranked schools, check which master’s routes exist, and compare what we know so far.</p><a class="text-link" href="#sources">How we research ↗</a></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit o2"></div><div class="orbit o3"></div><span class="art-year">2027</span><span class="art-caption">A WORLD OF POSSIBILITIES</span></div></section><div class="stats stats-areas">${programAreaStatsHtml()}</div>${rankingIntro()}<section aria-labelledby="programs-heading"><div class="section-row"><h2 id="programs-heading">Explore the ranked schools</h2><span id="result-count" aria-live="polite"></span></div><div class="toolbar"><div class="tabs" aria-label="Program area">${programAreaTabsHtml()}</div><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search programs</span><input id="program-search" type="search" placeholder="School, degree or academic focus…" value="${esc(query)}"></label></div><div class="toolbar secondary-toolbar"><label class="filter-label">Show <select class="filter-select" id="route-filter">${['All routes','Restrictions & exceptions','With tuition reference'].map(x=>`<option value="${x}" ${routeFilter===x?'selected':''}>${x}</option>`).join('')}</select></label><div class="tabs" aria-label="Display format">${['table','cards'].map(x=>`<button data-view="${x}" aria-pressed="${view===x}">${x==='table'?'Ranking table':'Profile cards'}</button>`).join('')}</div><a class="text-link" href="./ranked-programs.csv" download>Download CSV ↓</a></div><div id="program-results"></div><div id="pagination" class="pagination" aria-label="Profile pages"></div><div class="notice"><span class="notice-icon" aria-hidden="true">ⓘ</span><div><b>Coverage is visible, not assumed.</b> Ranked-school coverage is complete through the cutoff for MBA and CS. MSF program rows are not ingested yet. Program research is preliminary: individual faculty, internship outcomes, scholarships and many tuition figures still need verification. Unknown costs never mean free tuition. 2027–28 prices are not assumed.</div></div></section><div class="bottom-grid"><section class="mini-panel"><div class="eyebrow">FUND YOUR NEXT STEP</div><h3>One award. A shared record.</h3><p>${scholarships.length} funding records track scope, eligibility and deadlines separately.</p><a href="#scholarships">Browse scholarship library ↗</a></section><section class="mini-panel"><div class="eyebrow">FOLLOW THE EVIDENCE</div><h3>Keep the degree in focus.</h3><p>An MBA ranking does not apply to every business master’s or MSF. A highly ranked CS department may not admit external master’s students.</p><div class="source-strip"><span>THE</span><span>QS</span><span>U.S. News</span></div></section></div>`;
 $('#program-search').addEventListener('input',e=>{query=e.target.value;page=1;renderProgramResults();});
 $('#route-filter').addEventListener('change',e=>{routeFilter=e.target.value;page=1;renderProgramResults();});
 renderProgramResults();
}
function rankingTable(list){return `<div class="table-wrap ranking-table"><table><caption class="sr-only">U.S. News ${rankingEdition}; ranked schools and degree routes</caption><thead><tr><th scope="col">Rank</th><th scope="col">School & degree route</th><th scope="col">Master’s application status</th><th scope="col">Tuition reference</th><th scope="col">Compare</th></tr></thead><tbody>${list.map((p,i)=>`${i===0||p.area!==list[i-1].area?`<tr class="category-row"><th colspan="5" scope="colgroup">${esc(programAreaByName(p.area)?.tableSectionTitle ?? p.area)} <small>· ${rankingEdition}</small></th></tr>`:''}<tr><td><span class="rank-badge">${rankLabel(p)}</span></td><th scope="row"><button class="school-link" data-program="${p.id}">${esc(p.short)} ↗</button><p class="degree">${esc(p.degree)}</p></th><td>${statusPill(p)}</td><td><strong>${money(p.tuition)}</strong>${p.tuition!==null?`<small class="table-cost-basis">${p.tuitionLabel} · ${p.period}</small>`:''}</td><td><label class="compare-toggle"><input type="checkbox" data-compare="${p.id}" ${selected.has(p.id)?'checked':''}><span class="sr-only">Compare ${esc(p.short)} ${p.kind}</span></label></td></tr>`).join('')}</tbody></table></div>`;}
function renderProgramResults(){
 const list=localizedSearch(filterPrograms('',area,routeFilter),query,document.documentElement.lang);
 $('#result-count').textContent=`${list.length} of ${programs.length} entries`;
 const chunk=paginate(list,page);page=chunk.current;
 const msfEmpty = area === 'Finance' && !list.length;
 $('#program-results').innerHTML=!list.length?`<div class="empty"><h2>${msfEmpty ? 'MSF catalog scaffold only.' : 'No matching schools.'}</h2><p>${msfEmpty ? 'No Master of Finance program rows are in the catalog yet. Ingest awaits gm greenlight; ids will use the *-msf suffix when approved.' : 'Try another search or reset the filters.'}</p>${msfEmpty ? '<a class="button secondary" href="#notes/05-finance%2FREADME.md">Read MSF id convention ↗</a>' : '<button class="button secondary" data-reset-programs>Reset filters</button>'}</div>`:view==='table'?rankingTable(list):`<div class="program-grid">${chunk.items.map(programCard).join('')}</div>`;
 $('#pagination').innerHTML=view==='cards'&&list.length?`<button class="button secondary" data-page="${page-1}" ${page===1?'disabled':''}>← Previous</button><span>Page ${page} of ${chunk.pages}</span><button class="button secondary" data-page="${page+1}" ${page===chunk.pages?'disabled':''}>Next →</button>`:'';
}
function showAwards(){
 $('#main').innerHTML=head('FUNDING, CONNECTED','Scholarship library','One record per opportunity, linked across relevant programs. Eligibility, deadlines and award coverage stay separate from admission decisions.')+`<div class="notice" style="margin:0 0 25px"><span class="notice-icon" aria-hidden="true">◇</span><div><b>Eligibility is not assumed.</b> Hong Kong and Taiwan requirements need separate verification. A reusable record does not mean an award can be held repeatedly or combined with other funding.</div></div><div class="toolbar"><label><span class="sr-only">Filter scholarship status</span><select class="filter-select" id="award-state">${['All records','Not marked closed','Closed'].map(s=>`<option value="${s}" ${s===awardState?'selected':''}>${translate(s)}</option>`).join('')}</select></label><label><span class="sr-only">${translate('HK eligible')}</span><select class="filter-select" id="award-hk">${['All','yes','no','unclear'].map(s=>`<option value="${s}" ${s===awardHkFilter?'selected':''}>${translate(s==='All'?'HK eligible (all)':`HK eligible: ${s}`)}</option>`).join('')}</select></label><label><span class="sr-only">${translate('TW eligible')}</span><select class="filter-select" id="award-tw">${['All','yes','no','unclear'].map(s=>`<option value="${s}" ${s===awardTwFilter?'selected':''}>${translate(s==='All'?'TW eligible (all)':`TW eligible: ${s}`)}</option>`).join('')}</select></label><label><span class="sr-only">${translate('PRC eligible')}</span><select class="filter-select" id="award-prc">${['All','yes','no','unclear'].map(s=>`<option value="${s}" ${s===awardPrcFilter?'selected':''}>${translate(s==='All'?'PRC eligible (all)':`PRC eligible: ${s}`)}</option>`).join('')}</select></label><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search scholarships</span><input id="award-search" type="search" placeholder="${translate('Search scholarships or institutions…')}" value="${esc(awardQuery)}"></label></div><div id="award-results" class="scholarship-grid" aria-live="polite"></div>`;
 $('#award-state').onchange=e=>{awardState=e.target.value;renderAwards();};$('#award-hk').onchange=e=>{awardHkFilter=e.target.value;renderAwards();};$('#award-tw').onchange=e=>{awardTwFilter=e.target.value;renderAwards();};$('#award-prc').onchange=e=>{awardPrcFilter=e.target.value;renderAwards();};$('#award-search').oninput=e=>{awardQuery=e.target.value;renderAwards();};renderAwards();
}
const awardTypePill=s=>{const label=awardTypeBadgeLabel(s.awardType);return label?`<span class="pill amber">${esc(label)}</span>`:'';};
function renderAwards(){const list=scholarships.filter(s=>[`${s.name} ${s.scope} ${s.type}`,translate(`${s.name} ${s.scope} ${s.type}`,'zh-Hant'),translate(`${s.name} ${s.scope} ${s.type}`,'zh-Hans')].some(text=>text.toLowerCase().includes(awardQuery.toLowerCase()))&&(awardState==='All records'||(awardState==='Closed'?s.tone==='red':s.tone!=='red'))&&awardRegionFilterMatch(s,awardHkFilter,awardTwFilter,awardPrcFilter));$('#award-results').innerHTML=list.length?list.map(s=>`<article class="award"><div><div class="eyebrow">${s.id} <span aria-hidden="true">/</span> ${s.type}</div><h2>${s.name}</h2><p>${s.description}</p><span class="pill">${s.scope}</span>${s.hkEligible||s.twEligible||s.prcEligible?`<div class="badge-row" style="margin-top:10px">${s.hkEligible?`<span class="pill">HK: ${s.hkEligible}</span>`:''}${s.twEligible?`<span class="pill">TW: ${s.twEligible}</span>`:''}${s.prcEligible?`<span class="pill">PRC: ${s.prcEligible}</span>`:''}</div>`:''}</div><div class="award-aside">${awardTypePill(s)}<span class="pill ${s.tone}">${s.state}</span><button class="button secondary" data-award="${s.id}">Read funding record ↗</button></div></article>`).join(''):`<div class="empty"><h2>No matching funding records.</h2><p>Try a broader search or a different status.</p></div>`;}
function showCompare(){
 const list=programs.filter(p=>selected.has(p.id));
 $('#main').innerHTML=head('SIDE BY SIDE','Find the meaningful differences.','Compare the available evidence, not just the price tag. Different degree types and cost periods are labeled explicitly.') + (list.length<2?`<div class="empty"><div class="eyebrow">${list.length} PROGRAM${list.length===1?'':'S'} SELECTED</div><h2>Bring two perspectives together.</h2><p>Select at least two programs from Explore programs to compare their research.</p><a class="button" href="#programs">Choose programs ↗</a></div>`:`<div class="notice" style="margin:0 0 22px"><span class="notice-icon">ⓘ</span><div><b>Check the category and billing basis.</b> Rankings belong to their own categories. Annual and first-year tuition references are not total degree costs. Compare route restrictions alongside academic fit.</div></div><div class="table-wrap"><table><caption class="sr-only">Comparison of selected master's programs</caption><thead><tr><th scope="col">Research dimension</th>${list.map(p=>`<th scope="col">${p.short}<p class="degree">${p.degree}</p><button class="remove" data-remove="${p.id}">Remove from comparison ×</button></th>`).join('')}</tr></thead><tbody>${[
 ['Category',p=>p.area+' · '+p.kind],['Orientation',p=>p.orientation],['Tuition reference',p=>`<strong>${money(p.tuition)}</strong><p>${p.tuitionLabel} · ${p.period}</p><p>${p.costNote}</p>`],['Other costs',p=>p.costDetail],['Application deadline',p=>p.deadline],['Internships',p=>p.internship],['Career outcomes',p=>outcomeShortLine(p.outcome)],['Faculty & research access',p=>p.faculty],['Funding',p=>p.funding],['U.S. News ranking',p=>`${rankLabel(p)} · ${p.ranking.category} · ${rankingEdition}`],['Master’s route',p=>p.availability],['Evidence sources',p=>`<div class="source-links">${p.sources.map(s=>external(...s)).join('')}</div>`]
 ].map(([label,value])=>`<tr><th scope="row">${label}</th>${list.map(p=>`<td>${value(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);
}
function policySourceLabel(url){try{const h=new URL(url).hostname.replace(/^www\./,'');if(h.includes('federalregister.gov'))return'Federal Register';if(h.includes('uscis.gov'))return'USCIS';if(h.includes('ice.gov'))return'ICE / SEVIS';if(h.includes('travel.state.gov'))return'U.S. State Department';if(h.includes('oiss.yale.edu'))return'Yale OISS';return h;}catch{return'Source';}}
function policyItemCard(item){const conf=item.confidence==='confirmed';return`<article class="policy-item" id="policy-${esc(item.id)}"><div class="policy-item-head"><h3 translate="no">${esc(item.title)}</h3><div class="badge-row"><span class="pill ${conf?'green':'amber'}">${conf?'Confirmed':'Developing'}</span>${item.school_specific?'<span class="pill amber">School-specific</span>':''}</div></div><p class="policy-summary" translate="no">${esc(item.summary)}</p><dl class="policy-facts"><dt>Slate impact</dt><dd translate="no">${esc(item.slate_impact)}</dd><dt>Affected</dt><dd><div class="tag-row">${item.affected.map(a=>`<span class="pill" translate="no">${esc(a)}</span>`).join('')}</div></dd><dt>Sources</dt><dd><div class="source-links">${item.sources.map(url=>external(policySourceLabel(url),url)).join('')}</div></dd></dl></article>`;}
function policySection(){return`<section class="policy-section" aria-labelledby="policy-heading"><div class="notice policy-disclaimer"><span class="notice-icon" aria-hidden="true">⚠</span><div><b>Not legal advice.</b> <span>Rules change; verify with official sources and school ISSS.</span></div></div><div class="section-row"><div><div class="eyebrow">VISAS & POLICY</div><h2 id="policy-heading">Policy & visa context (Fall 2027)</h2></div><span>Baseline scan · <time datetime="${policy.asOf}" translate="no">${policy.asOf}</time></span></div><div class="policy-list">${policy.items.map(policyItemCard).join('')}</div></section>`;}
function showSources(){ $('#main').innerHTML=head('KNOW WHAT IS BEHIND THE CLAIM','Sources & methodology','Use rankings to discover possibilities. Use primary sources to verify costs, requirements and opportunities. Keep the distinction visible.')+rankingIntro()+`<div class="source-grid">${sources.map(s=>`<article class="source-card"><div class="source-head"><strong>${s.initials}</strong><span>${s.tag}</span></div><h2>${s.name}</h2><p>${s.text}</p><p class="limit">${s.limit}</p><div class="source-links">${external('Visit source',s.url)}</div></article>`).join('')}</div>${policySection()}<div class="bottom-grid"><section class="mini-panel"><div class="eyebrow">COSTS THAT CAN BE COMPARED</div><h3>Keep the year and basis attached.</h3><p>Record tuition, required terms, fees, insurance and living expenses separately. Scholarships reduce net cost only when awarded or modeled as an uncertain scenario. Loans are not scholarships.</p></section><section class="mini-panel"><div class="eyebrow">OPPORTUNITIES WITH EVIDENCE</div><h3>Support is not a placement guarantee.</h3><p>Separate required internships, optional placements and career services. Check the reporting cohort, denominator and international-student outcomes before making claims.</p></section></div><div class="notice"><span class="notice-icon">ⓘ</span><div><b>Verified, prior-year, inferred or unknown.</b> Every finding should retain its source and research date. Missing data never means zero opportunity. <a href="#notes/01-sources%2Fsource-guide.md">Read the full source guide ↗</a></div></div>`;}
function inline(text,base){let s=esc(text);s=s.replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{if(/^https:\/\//.test(url))return `<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;if(!url.startsWith('/')&&!url.includes(':')){const parts=base.split('/').slice(0,-1);for(const p of url.split('/')){if(p==='..')parts.pop();else if(p!=='.')parts.push(p);}const file=parts.join('/');if(notes.some(n=>n.path===file))return `<a href="#notes/${encodeURIComponent(file)}" data-note-link>${label}</a>`;}return label;});return s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');}
function markdown(body,base){const lines=body.split('\n');let html='',inList=false;for(let i=0;i<lines.length;i++){const line=lines[i];if(!/^(- |\d+\. )/.test(line)&&inList){html+='</ul>';inList=false;}if(line.startsWith('|')){const rows=[];while(i<lines.length&&lines[i].startsWith('|'))rows.push(lines[i++]);i--;html+='<div class="table-wrap"><table>';rows.filter(r=>!/^\|[\s:|\-]+\|$/.test(r)).forEach((r,j)=>{html+=j===0?'<thead><tr>':'<tr>';html+=r.split('|').slice(1,-1).map(c=>`<${j===0?'th':'td'}>${inline(c.trim(),base)}</${j===0?'th':'td'}>`).join('');html+=j===0?'</tr></thead><tbody>':'</tr>';});html+='</tbody></table></div>';continue;}const h=line.match(/^(#{1,3}) (.*)/);if(h){html+=`<h${h[1].length}>${inline(h[2],base)}</h${h[1].length}>`;continue;}if(/^(- |\d+\. )/.test(line)){if(!inList){html+='<ul>';inList=true;}html+=`<li>${inline(line.replace(/^(- |\d+\. )/,''),base)}</li>`;}else if(line.trim())html+=`<p>${inline(line,base)}</p>`;}if(inList)html+='</ul>';return html;}
function noteListButtons(activePath){return notes.map(n=>`<button data-note="${esc(n.path)}" class="${n.path===activePath?'active':''}" aria-current="${n.path===activePath?'page':'false'}">${esc(n.title)}</button>`).join('');}
function showNotes(){const note=notes.find(n=>n.path===activeNote)||notes[0];const notebook=document.querySelector('.notebook');if(notebook){const list=notebook.querySelector('.note-list');list?.querySelectorAll('button[data-note]').forEach(btn=>{const active=btn.dataset.note===note.path;btn.classList.toggle('active',active);btn.setAttribute('aria-current',active?'page':'false');});const doc=notebook.querySelector('.document');if(doc)doc.innerHTML=`<span class="pill">Original English document</span>${markdown(note.body,note.path)}`;list?.querySelector(`button[data-note="${CSS.escape(note.path)}"]`)?.scrollIntoView({block:'nearest'});return;}$('#main').innerHTML=head('THE COMPLETE RESEARCH RECORD','Open the notebook.','Read the original findings, scope, evidence rules and reusable dossier template. These documents are the foundation of the collection.')+`<div class="notebook"><nav class="note-list" aria-label="Research documents">${noteListButtons(note.path)}</nav><article class="document" translate="no" lang="en"><span class="pill">Original English document</span>${markdown(note.body,note.path)}</article></div>`;}
function programDetail(id){
 const p=programs.find(p=>p.id===id);if(!p)return;
 $('#dialog-content').innerHTML=`<article class="dossier"><div class="eyebrow">${esc(p.university)} / ${esc(programAreaByName(p.area)?.detailEyebrow ?? p.area)}</div><h2 id="dialog-title">${esc(p.degree)}</h2><div class="badge-row"><span class="pill">${rankLabel(p)} · U.S. News</span><span class="pill">Checked ${checked}</span></div><p class="ranking-caption">${p.ranking.category} · ${rankingEdition}. ${external('Ranking reproduction',p.ranking.reproduction)}</p>${statusPill(p)}<h3>Academic direction & degree route</h3><p>${esc(p.academic)}</p><div class="fact-box"><div class="cost-label">${p.tuitionLabel} · ${p.period}</div><strong>${money(p.tuition)}${p.tuition!==null?' USD':''}</strong><p>${p.costNote}</p><p>${p.costDetail}</p></div><h3>Admissions & timing</h3><p>${p.deadline}. Check the official program page for the exact round, time zone, prerequisites and international eligibility.</p><h3>Faculty & research access</h3><p>${p.faculty}</p>${careerSection(p)}<h3>Scholarships & funding</h3><p>${p.funding}</p><div class="inline-actions">${p.scholarships.map(id=>{const a=scholarships.find(s=>s.id===id);return `<button class="button secondary" data-award="${id}">${a.name}${a.tone==='red'?' · Closed':''} ↗</button>`;}).join('')}</div><h3>Evidence still needed</h3><ul class="checklist">${['2027–28 tuition and full-degree cost','Individual faculty fit and supervision availability','Internship outcomes for international students','Personal scholarship eligibility','THE / QS cross-comparison'].map(t=>`<li>${t}<span>TO VERIFY</span></li>`).join('')}</ul><h3>Follow the sources</h3><div class="source-links">${p.sources.map(s=>external(...s)).join('')}</div><a class="text-link" data-note-link href="#notes/${encodeURIComponent(p.note)}">Read program research note ↗</a></article>`;openDialog();
}
function awardDetail(id){const s=scholarships.find(s=>s.id===id);if(!s)return;$('#dialog-content').innerHTML=`<article class="dossier"><div class="eyebrow">${s.id} / ${s.type}</div><h2 id="dialog-title">${s.name}</h2><div class="badge-row"><span class="pill ${s.tone}">${s.state}</span><span class="pill">${s.scope}</span>${awardTypePill(s)}${s.hkEligible?`<span class="pill">HK eligible: ${s.hkEligible}</span>`:''}${s.twEligible?`<span class="pill">TW eligible: ${s.twEligible}</span>`:''}${s.prcEligible?`<span class="pill">PRC eligible: ${s.prcEligible}</span>`:''}</div><p>${s.description}</p><h3>Eligibility & program scope</h3><p>${s.eligibility}</p><h3>Award coverage</h3><p>${s.amount}. Renewal and stacking rules require verification.</p><h3>Deadline & application</h3><p>${s.deadline}.</p>${s.id==='SCH-002'?'<p>Applicants who already submitted a KHS application must also apply to their Stanford degree by the earlier of the program’s KHS deadline or 1 December 2026.</p>':''}<div class="notice"><div>Checked ${checked}. This record does not establish an individual applicant’s eligibility or award amount.</div></div><h3>Related program research</h3><div class="inline-actions">${programs.filter(p=>p.scholarships.includes(s.id)).map(p=>`<button class="button secondary" data-program="${p.id}">${p.short} · ${p.kind} ↗</button>`).join('')||'<p>No verified program links in the current collection.</p>'}</div><div class="source-links">${external('Official award source',s.url)}</div><a class="text-link" data-note-link href="#notes/${encodeURIComponent(s.note)}">Read original funding record ↗</a></article>`;openDialog();}
function openDialog(){if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;$('#close-dialog').focus();}
$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close();}});
document.addEventListener('click',e=>{
 const btn=e.target.closest('button,a');if(!btn)return;
 if(btn.hasAttribute('data-area')){area=btn.dataset.area;page=1;document.querySelectorAll('[data-area]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.area===area));renderProgramResults();}
 if(btn.hasAttribute('data-reset-programs')){area='All programs';query='';routeFilter='All routes';page=1;showPrograms();}
 if(btn.dataset.page){page=Number(btn.dataset.page);renderProgramResults();$('#programs-heading').scrollIntoView();}
 if(btn.dataset.view){view=btn.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===view));renderProgramResults();}
 if(btn.dataset.program)programDetail(btn.dataset.program);
 if(btn.dataset.award)awardDetail(btn.dataset.award);
 if(btn.dataset.remove){selected.delete(btn.dataset.remove);saveSelection();showCompare();}
 if(btn.dataset.note)location.hash='notes/'+encodeURIComponent(btn.dataset.note);
 if(btn.hasAttribute('data-note-link'))$('#detail').close();
});
document.addEventListener('change',e=>{if(e.target.dataset.compare){const id=e.target.dataset.compare;if(e.target.checked && selected.size >= 4){e.target.checked=false;toast('Compare up to four programs at a time. Remove one to add another.');return;}e.target.checked?selected.add(id):selected.delete(id);saveSelection();toast(`${selected.size} program${selected.size===1?'':'s'} selected for comparison`);}});
let currentView='programs';
function route(){const [page,doc]=location.hash.slice(1).split('/');if(doc){try{activeNote=decodeURIComponent(doc);}catch{activeNote='README.md';}}const current=['programs','scholarships','compare','sources','notes'].includes(page)?page:'programs';const noteSwitch=current==='notes'&&currentView==='notes'&&!!doc;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===current);if(a.dataset.nav===current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});({programs:showPrograms,scholarships:showAwards,compare:showCompare,sources:showSources,notes:showNotes})[current]();document.title=`${{programs:'Explore programs',scholarships:'Scholarship library',compare:'Compare programs',sources:'Sources & methodology',notes:'Research notebook'}[current]} — Fieldnotes`;if(!noteSwitch)window.scrollTo(0,0);currentView=current;}
document.querySelector('[data-nav=programs] .nav-count').textContent=programs.length;
document.querySelector('[data-nav=scholarships] .nav-count').textContent=scholarships.length;
window.addEventListener('hashchange',()=>{$('#detail').close();route();});route();

